<script setup lang="ts">
import { ref } from 'vue';import { api } from '../../services/api';const title=ref('');const content=ref('');const level=ref('IMPORTANT');const hours=ref(24);const working=ref(false);
async function publish(){if(!title.value||!content.value)return uni.showToast({title:'请填写标题和正文',icon:'none'});working.value=true;try{const deadlineAt=new Date(Date.now()+hours.value*3600000).toISOString();const dto={title:title.value,content:content.value,level:level.value,requiresConfirmation:true,deadlineAt,recipientSelection:{mode:'ALL_ACTIVE'}};const preview:any=await api('/notices/recipient-preview','POST',dto.recipientSelection);const ok=await new Promise<boolean>(resolve=>uni.showModal({title:'确认发布',content:`将向 ${preview.recipientCount} 人发布，${hours.value} 小时内确认。`,success:r=>resolve(r.confirm)}));if(!ok)return;const draft:any=await api('/notices','POST',dto);await api(`/notices/${draft.id}/publish`,'POST');uni.showToast({title:'发布成功',icon:'success'});setTimeout(()=>uni.navigateBack(),500);}catch(e:any){uni.showToast({title:e.message,icon:'none'});}finally{working.value=false;}}
</script><template><view class="page"><view class="card form"><text>通知标题</text><input v-model="title" placeholder="请输入标题"/><text>正文</text><textarea v-model="content" placeholder="请输入通知内容"/><text>重要程度</text><picker :range="['NORMAL','IMPORTANT','URGENT']" @change="level=['NORMAL','IMPORTANT','URGENT'][Number($event.detail.value)]"><view class="picker">{{level}}</view></picker><text>确认时限（小时）</text><input v-model.number="hours" type="number"/></view><button class="primary-btn" :loading="working" @tap="publish">预览并发布</button></view></template><style scoped>.form>text{display:block;margin:22rpx 0 10rpx;font-weight:700}.form input,.form textarea,.picker{padding:20rpx;border:1px solid #dce7e8;border-radius:14rpx;background:#f8fbfb}.form textarea{min-height:300rpx}</style>
